// analyzer/constructors.ts:66
// Fetches and binds the __new__ method from a class.
/// TS defaults: diag = undefined, additionalFlags = MemberAccessFlags.SkipObjectBaseClass.
pub fn get_bound_new_method(
    evaluator: &TypeEvaluator,
    error_node: ExpressionNode,
    type_: ClassType,
    diag: Option<P<DiagnosticAddendum>>,
    additional_flags: MemberAccessFlags,
) -> Option<P<TypeResult>> {
    let flags = MemberAccessFlags::SkipClassMembers
        | MemberAccessFlags::SkipAttributeAccessOverride
        | MemberAccessFlags::TreatConstructorAsClassMethod
        | additional_flags;

    evaluator.get_type_of_bound_member(
        Some(error_node),
        type_,
        "__new__",
        &EvaluatorUsage {
            method: "get".to_string(),
            set_type: None,
            set_error_node: None,
            set_expected_type_diag: None,
        },
        diag,
        flags,
        None,
        0,
    )
}

// analyzer/constructors.ts:83
// Fetches and binds the __init__ method from a class instance.
/// TS defaults: diag = undefined, additionalFlags = MemberAccessFlags.SkipObjectBaseClass.
pub fn get_bound_init_method(
    evaluator: &TypeEvaluator,
    error_node: ExpressionNode,
    type_: ClassType,
    diag: Option<P<DiagnosticAddendum>>,
    additional_flags: MemberAccessFlags,
) -> Option<P<TypeResult>> {
    let flags = MemberAccessFlags::SkipInstanceMembers
        | MemberAccessFlags::SkipAttributeAccessOverride
        | additional_flags;

    evaluator.get_type_of_bound_member(
        Some(error_node),
        type_,
        "__init__",
        &EvaluatorUsage {
            method: "get".to_string(),
            set_type: None,
            set_error_node: None,
            set_expected_type_diag: None,
        },
        diag,
        flags,
        None,
        0,
    )
}

// analyzer/constructors.ts:97
// Fetches and binds the __call__ method from a class or its metaclass.
pub fn get_bound_call_method(
    evaluator: &TypeEvaluator,
    error_node: ExpressionNode,
    type_: ClassType,
) -> Option<P<TypeResult>> {
    evaluator.get_type_of_bound_member(
        Some(error_node),
        type_,
        "__call__",
        &EvaluatorUsage {
            method: "get".to_string(),
            set_type: None,
            set_error_node: None,
            set_expected_type_diag: None,
        },
        /* diag */ None,
        MemberAccessFlags::SkipInstanceMembers
            | MemberAccessFlags::SkipTypeBaseClass
            | MemberAccessFlags::SkipAttributeAccessOverride,
        None,
        0,
    )
}

// analyzer/constructors.ts:113
// Matches the arguments of a call to the constructor for a class.
// If successful, it returns the resulting (specialized) object type that
// is allocated by the constructor. If unsuccessful, it reports diagnostics.
pub fn validate_constructor_args(
    evaluator: &TypeEvaluator,
    error_node: ExpressionNode,
    arg_list: &[Arg],
    type_: ClassType,
    skip_unknown_arg_check: Option<bool>,
    inference_context: Option<P<InferenceContext>>,
) -> CallResult {
    let mut type_ = type_;

    // If this is an unspecialized generic type alias, specialize it now
    // using default type argument values.
    let alias_info = type_
        .props
        .borrow()
        .as_ref()
        .and_then(|props| props.type_alias_info.clone());
    if let Some(alias_info) = alias_info
        && alias_info.shared.type_params.borrow().is_some()
        && alias_info.type_args.is_none()
    {
        type_ = ClassType(apply_solved_type_vars(
            type_.0,
            &ConstraintSolution::new(None),
            &ApplyTypeVarOptions {
                type_class_type: None,
                replace_unsolved: Some(ApplyTypeVarOptionsReplaceUnsolved {
                    scope_ids: vec![alias_info.shared.type_var_scope_id.clone()],
                    tuple_class_type: evaluator.get_tuple_class_type(),
                    unsolved_exempt_type_vars: None,
                    use_unknown: None,
                    eliminate_unsolved_in_unions: None,
                }),
            },
        ));
    }

    let metaclass_result = validate_metaclass_call(
        evaluator,
        error_node,
        arg_list,
        type_,
        skip_unknown_arg_check,
        inference_context,
        /* useSpeculativeModeForArgs */ true,
    );

    if let Some(metaclass_result) = metaclass_result {
        let metaclass_return_type = metaclass_result
            .return_type
            .unwrap_or_else(|| UnknownType::create(false).0);

        // If there a custom `__call__` method on the metaclass that returns
        // something other than an instance of the class, assume that it
        // overrides the normal `type.__call__` logic and don't perform the usual
        // __new__ and __init__ validation.
        if metaclass_result.argument_errors.unwrap_or(false)
            || should_skip_new_and_init_evaluation(evaluator, type_, metaclass_return_type)
        {
            validate_metaclass_call(
                evaluator,
                error_node,
                arg_list,
                type_,
                skip_unknown_arg_check,
                inference_context,
                /* useSpeculativeModeForArgs */ false,
            );

            return metaclass_result;
        }
    }

    // Determine whether the class overrides the object.__new__ method.
    let new_method_diag = DiagnosticAddendum::new();
    let new_method_type_result = get_bound_new_method(
        evaluator,
        error_node,
        type_,
        Some(new_method_diag),
        MemberAccessFlags::SkipObjectBaseClass,
    );
    if new_method_type_result.is_some_and(|result| result.type_errors.get().unwrap_or(false)) {
        evaluator.add_diagnostic(
            DiagnosticRule::reportGeneralTypeIssues,
            &new_method_diag.get_string(
                DEFAULT_MAX_DIAGNOSTIC_DEPTH,
                DEFAULT_MAX_DIAGNOSTIC_LINE_COUNT,
            ),
            error_node,
            None,
        );
    }

    let use_constructor_transform = has_constructor_transform(type_);

    // If there is a constructor transform, evaluate all arguments speculatively
    // so we can later re-evaluate them in the context of the transform.
    let mut return_result = evaluator.use_speculative_mode(
        if use_constructor_transform {
            Some(error_node)
        } else {
            None
        },
        &mut || {
            validate_new_and_init_methods(
                evaluator,
                error_node,
                arg_list,
                type_,
                skip_unknown_arg_check,
                inference_context,
                new_method_type_result,
            )
        },
        None,
    );

    let mut validated_arg_expressions =
        !use_constructor_transform || return_result.argument_errors.unwrap_or(false);

    // Apply a constructor transform if applicable.
    if use_constructor_transform {
        if return_result.argument_errors.unwrap_or(false) {
            // If there were errors when validating the __new__ and __init__ methods,
            // we need to re-evaluate the arguments to generate error messages because
            // we previously evaluated them speculatively.
            validate_new_and_init_methods(
                evaluator,
                error_node,
                arg_list,
                type_,
                skip_unknown_arg_check,
                inference_context,
                new_method_type_result,
            );

            validated_arg_expressions = true;
        } else if let Some(return_type) = return_result.return_type {
            let transformed = apply_constructor_transform(
                evaluator,
                error_node,
                arg_list,
                type_,
                &FunctionResult {
                    argument_errors: return_result.argument_errors.unwrap_or(false),
                    return_type,
                    is_type_incomplete: return_result.is_type_incomplete.unwrap_or(false),
                },
            );

            if let Some(transformed) = transformed {
                return_result.return_type = Some(transformed.return_type);

                if transformed.is_type_incomplete {
                    return_result.is_type_incomplete = Some(true);
                }

                if transformed.argument_errors {
                    return_result.argument_errors = Some(true);
                }

                validated_arg_expressions = true;
            }
        }
    }

    // If we weren't able to validate the args, analyze the expressions here
    // to mark symbols referenced and report expression evaluation errors.
    if !validated_arg_expressions {
        for arg in arg_list {
            if let Some(value_expression) = arg.value_expression()
                && !evaluator.is_speculative_mode_in_use(Some(value_expression))
            {
                evaluator.get_type_of_expression(value_expression, EvalFlags::None, None);
            }
        }
    }

    return_result
}

// analyzer/constructors.ts:243
// The TypeScript's last write to validatedArgExpressions is never read.
#[allow(unused_assignments)]
pub(crate) fn validate_new_and_init_methods(
    evaluator: &TypeEvaluator,
    error_node: ExpressionNode,
    arg_list: &[Arg],
    type_: ClassType,
    skip_unknown_arg_check: Option<bool>,
    inference_context: Option<P<InferenceContext>>,
    new_method_type_result: Option<P<TypeResult>>,
) -> CallResult {
    let mut skip_unknown_arg_check = skip_unknown_arg_check;
    let mut return_type: Option<P<Type>> = None;
    let mut validated_arg_expressions = false;
    let mut argument_errors = false;
    let mut is_type_incomplete = false;
    let mut overloads_used_for_call: Vec<FunctionType> = Vec::new();
    let mut new_method_return_type: Option<P<Type>> = None;

    // Validate __new__ if it is present.
    if let Some(new_method_type_result) = new_method_type_result {
        // Use speculative mode for arg expressions because we don't know whether
        // we'll need to re-evaluate these expressions later for __init__.
        let new_call_result = validate_new_method(
            evaluator,
            error_node,
            arg_list,
            type_,
            skip_unknown_arg_check,
            inference_context,
            new_method_type_result,
            /* useSpeculativeModeForArgs */ true,
        );

        if new_call_result.argument_errors.unwrap_or(false) {
            argument_errors = true;
        } else {
            append_array(
                &mut overloads_used_for_call,
                new_call_result
                    .overloads_used_for_call
                    .as_deref()
                    .unwrap_or_default(),
            );
        }

        if new_call_result.is_type_incomplete.unwrap_or(false) {
            is_type_incomplete = true;
        }

        new_method_return_type = new_call_result.return_type;
    }

    let new_method_return_type: P<Type> = match new_method_return_type {
        Some(new_method_return_type)
            if !is_default_new_method(new_method_type_result.map(|result| result.type_.get())) =>
        {
            if is_unknown(new_method_return_type)
                || new_method_type_result.is_some_and(|result| is_any(result.type_.get()))
            {
                // If the __new__ method returns Unknown, we'll ignore its return
                // type and assume that it returns Self.
                apply_solved_type_vars(
                    ClassType::clone_as_instance(type_, true).0,
                    &ConstraintSolution::new(None),
                    &ApplyTypeVarOptions {
                        type_class_type: None,
                        replace_unsolved: Some(ApplyTypeVarOptionsReplaceUnsolved {
                            scope_ids: get_type_var_scope_ids(type_.0),
                            tuple_class_type: evaluator.get_tuple_class_type(),
                            unsolved_exempt_type_vars: None,
                            use_unknown: None,
                            eliminate_unsolved_in_unions: None,
                        }),
                    },
                )
            } else {
                new_method_return_type
            }
        }
        // If there is no __new__ method or it uses a default signature,
        // (cls, *args, **kwargs) -> Self, allow the __init__ method to
        // determine the specialized type of the class.
        _ => ClassType::clone_as_instance(type_, true).0,
    };

    let mut init_method_type_result: Option<P<TypeResult>> = None;

    // If there were errors evaluating the __new__ method, assume that __new__
    // returns the class instance and proceed accordingly. This may produce
    // false positives in some cases, but it will prevent false negatives
    // if the __init__ method also produces type errors (perhaps unrelated
    // to the errors in the __new__ method).
    if argument_errors {
        init_method_type_result = Some(P::new_eval(TypeResult::new(convert_to_instance(
            type_.0, true,
        ))));
    }

    // Validate __init__ if it's present.
    if !is_never(new_method_return_type)
        && !should_skip_init_evaluation(evaluator, type_, new_method_return_type)
        && is_class_instance(new_method_return_type)
    {
        // If the __new__ method returned the same type as the class it's constructing
        // but didn't supply solved type arguments, we'll ignore its specialized return
        // type and rely on the __init__ method to supply the type arguments instead.
        let mut init_method_bind_to_type = ClassType(new_method_return_type);
        if init_method_bind_to_type
            .d()
            .priv_
            .borrow()
            .type_args
            .as_ref()
            .is_some_and(|type_args| type_args.iter().any(|&type_arg| is_unknown(type_arg)))
        {
            init_method_bind_to_type = ClassType::clone_as_instance(type_, true);
        }

        // Determine whether the class overrides the object.__init__ method.
        let init_method_diag = DiagnosticAddendum::new();
        init_method_type_result = get_bound_init_method(
            evaluator,
            error_node,
            init_method_bind_to_type,
            Some(init_method_diag),
            MemberAccessFlags::SkipObjectBaseClass,
        );
        if init_method_type_result.is_some_and(|result| result.type_errors.get().unwrap_or(false)) {
            evaluator.add_diagnostic(
                DiagnosticRule::reportGeneralTypeIssues,
                &init_method_diag.get_string(
                    DEFAULT_MAX_DIAGNOSTIC_DEPTH,
                    DEFAULT_MAX_DIAGNOSTIC_LINE_COUNT,
                ),
                error_node,
                None,
            );
        }

        // Validate __init__ if it's present.
        if let Some(init_method_type_result) = init_method_type_result {
            let init_call_result = validate_init_method(
                evaluator,
                error_node,
                arg_list,
                init_method_bind_to_type,
                skip_unknown_arg_check,
                inference_context,
                init_method_type_result.type_.get(),
            );

            if init_call_result.argument_errors.unwrap_or(false) {
                argument_errors = true;
            } else if let Some(init_overloads) = &init_call_result.overloads_used_for_call {
                overloads_used_for_call.extend_from_slice(init_overloads);
            }

            if init_call_result.is_type_incomplete.unwrap_or(false) {
                is_type_incomplete = true;
            }

            return_type = init_call_result.return_type;
            validated_arg_expressions = true;
            skip_unknown_arg_check = Some(true);
        }
    }

    if !validated_arg_expressions && let Some(new_method_type_result) = new_method_type_result {
        // If we skipped the __init__ method and the __new__ method was evaluated only
        // speculatively, evaluate it non-speculatively now so we can report errors.
        if !evaluator.is_speculative_mode_in_use(Some(error_node)) {
            validate_new_method(
                evaluator,
                error_node,
                arg_list,
                type_,
                skip_unknown_arg_check,
                inference_context,
                new_method_type_result,
                /* useSpeculativeModeForArgs */ false,
            );
        }

        validated_arg_expressions = true;
        return_type = Some(new_method_return_type);
    }

    // If the class doesn't override object.__new__ or object.__init__, use the
    // fallback constructor type evaluation for the `object` class.
    if new_method_type_result.is_none() && init_method_type_result.is_none() {
        let call_result = validate_fallback_constructor_call(
            evaluator,
            error_node,
            arg_list,
            type_,
            inference_context,
        );

        if call_result.argument_errors.unwrap_or(false) {
            argument_errors = true;
        } else if let Some(fallback_overloads) = &call_result.overloads_used_for_call {
            append_array(&mut overloads_used_for_call, fallback_overloads);
        }

        if call_result.is_type_incomplete.unwrap_or(false) {
            is_type_incomplete = true;
        }

        return_type = Some(
            call_result
                .return_type
                .unwrap_or_else(|| UnknownType::create(false).0),
        );
    }

    CallResult {
        argument_errors: Some(argument_errors),
        return_type,
        is_type_incomplete: Some(is_type_incomplete),
        overloads_used_for_call: Some(overloads_used_for_call),
        ..Default::default()
    }
}

// analyzer/constructors.ts:410
// Evaluates the __new__ method for type correctness. If useSpeculativeModeForArgs
// is true, use speculative mode to evaluate the arguments (unless an argument
// error is produced, in which case it's OK to use speculative mode).
pub(crate) fn validate_new_method(
    evaluator: &TypeEvaluator,
    error_node: ExpressionNode,
    arg_list: &[Arg],
    type_: ClassType,
    skip_unknown_arg_check: Option<bool>,
    inference_context: Option<P<InferenceContext>>,
    new_method_type_result: P<TypeResult>,
    use_speculative_mode_for_args: bool,
) -> CallResult {
    let mut new_return_type: Option<P<Type>> = None;
    let mut is_type_incomplete = false;
    let mut argument_errors = false;
    let mut overloads_used_for_call: Vec<FunctionType> = Vec::new();

    let constraints = ConstraintTracker::new();

    let call_result = evaluator.use_speculative_mode(
        if use_speculative_mode_for_args {
            Some(error_node)
        } else {
            None
        },
        &mut || {
            evaluator.validate_call_args(
                error_node,
                arg_list,
                new_method_type_result,
                Some(constraints),
                skip_unknown_arg_check,
                inference_context,
                0,
            )
        },
        Some(&SpeculativeModeOptions {
            dependent_type: Some(new_method_type_result.type_.get()),
            allow_diagnostics: None,
        }),
    );

    if call_result.is_type_incomplete.unwrap_or(false) {
        is_type_incomplete = true;
    }

    if call_result.argument_errors.unwrap_or(false) {
        argument_errors = true;

        // Evaluate the arguments in a non-speculative manner to generate any diagnostics.
        evaluator.validate_call_args(
            error_node,
            arg_list,
            new_method_type_result,
            Some(constraints),
            skip_unknown_arg_check,
            inference_context,
            0,
        );
    } else {
        new_return_type = call_result.return_type;

        if overloads_used_for_call.is_empty()
            && let Some(call_overloads) = &call_result.overloads_used_for_call
        {
            overloads_used_for_call.extend_from_slice(call_overloads);
        }
    }

    let new_return_type = if let Some(mut new_return_type) = new_return_type {
        // Special-case the 'tuple' type specialization to use the homogenous
        // arbitrary-length form.
        if is_class_instance(new_return_type)
            && is_tuple_class(ClassType(new_return_type))
            && ClassType(new_return_type)
                .d()
                .priv_
                .borrow()
                .tuple_type_args
                .is_none()
        {
            let single_type_arg = ClassType(new_return_type)
                .d()
                .priv_
                .borrow()
                .type_args
                .as_ref()
                .filter(|type_args| type_args.len() == 1)
                .map(|type_args| type_args[0]);
            if let Some(single_type_arg) = single_type_arg {
                new_return_type = specialize_tuple_class(
                    ClassType(new_return_type),
                    &[TupleTypeArg {
                        type_: single_type_arg,
                        is_unbounded: true,
                        is_optional: None,
                    }],
                    true,
                    false,
                )
                .0;
            }

            new_return_type = apply_expected_type_for_tuple_constructor(
                ClassType(new_return_type),
                inference_context,
            )
            .0;
        }
        new_return_type
    } else {
        apply_expected_type_for_constructor(evaluator, type_, inference_context, constraints)
    };

    CallResult {
        argument_errors: Some(argument_errors),
        return_type: Some(new_return_type),
        is_type_incomplete: Some(is_type_incomplete),
        overloads_used_for_call: Some(overloads_used_for_call),
        ..Default::default()
    }
}

// analyzer/constructors.ts:485
pub(crate) fn validate_init_method(
    evaluator: &TypeEvaluator,
    error_node: ExpressionNode,
    arg_list: &[Arg],
    type_: ClassType,
    skip_unknown_arg_check: Option<bool>,
    inference_context: Option<P<InferenceContext>>,
    init_method_type: P<Type>,
) -> CallResult {
    let mut is_type_incomplete = false;
    let mut argument_errors = false;
    let mut overloads_used_for_call: Vec<FunctionType> = Vec::new();

    let constraints = ConstraintTracker::new();
    if type_.d().priv_.borrow().type_args.is_some() {
        add_constraints_for_expected_type(
            evaluator,
            type_,
            type_.0,
            constraints,
            /* liveTypeVarScopes */ None,
            None,
        );
    }

    let return_type_override = self_specialize_class(type_, None);
    let init_inference_context = inference_context.map(|inference_context| {
        P::new_eval(InferenceContext {
            expected_type: Cell::new(inference_context.expected_type.get()),
            is_type_incomplete: inference_context.is_type_incomplete,
            return_type_override: Some(return_type_override.0),
        })
    });
    let call_result = evaluator.validate_call_args(
        error_node,
        arg_list,
        P::new_eval(TypeResult::new(init_method_type)),
        Some(constraints),
        skip_unknown_arg_check,
        init_inference_context,
        0,
    );

    // Overload evaluation keeps the ordinary __init__ return as a placeholder
    // and carries argument-dependent constructed types through this separate field,
    // including when union-expanded argument lists are combined.
    let return_type =
        if let Some(specialized_init_self_type) = call_result.specialized_init_self_type {
            map_subtypes(
                specialized_init_self_type,
                &mut |specialized_init_self_subtype| {
                    let mut adjusted_class_type = type_;
                    if is_class_instance(specialized_init_self_subtype)
                        && ClassType::is_same_generic_class(
                            ClassType(specialized_init_self_subtype),
                            adjusted_class_type,
                            0,
                        )
                    {
                        adjusted_class_type = ClassType::clone_as_instantiable(
                            ClassType(specialized_init_self_subtype),
                            true,
                        );
                    }

                    if !type_
                        .d()
                        .priv_
                        .borrow()
                        .is_type_arg_explicit
                        .unwrap_or(false)
                        && (is_any(specialized_init_self_subtype)
                            || is_unknown(specialized_init_self_subtype))
                    {
                        return Some(specialized_init_self_subtype);
                    }

                    Some(apply_expected_type_for_constructor(
                        evaluator,
                        adjusted_class_type,
                        /* inferenceContext */ None,
                        constraints,
                    ))
                },
                None,
            )
        } else {
            apply_expected_type_for_constructor(
                evaluator,
                type_,
                /* inferenceContext */ None,
                constraints,
            )
        };

    if call_result.is_type_incomplete.unwrap_or(false) {
        is_type_incomplete = true;
    }

    if call_result.argument_errors.unwrap_or(false) {
        argument_errors = true;
    } else if let Some(call_overloads) = &call_result.overloads_used_for_call {
        overloads_used_for_call.extend_from_slice(call_overloads);
    }

    CallResult {
        argument_errors: Some(argument_errors),
        return_type: Some(return_type),
        is_type_incomplete: Some(is_type_incomplete),
        overloads_used_for_call: Some(overloads_used_for_call),
        ..Default::default()
    }
}

// analyzer/constructors.ts:555
pub(crate) fn validate_fallback_constructor_call(
    evaluator: &TypeEvaluator,
    error_node: ExpressionNode,
    arg_list: &[Arg],
    type_: ClassType,
    inference_context: Option<P<InferenceContext>>,
) -> CallResult {
    // Bind the __new__ method from the object class.
    let new_method_type = get_bound_new_method(
        evaluator,
        error_node,
        type_,
        /* diag */ None,
        /* additionalFlags */ MemberAccessFlags::Default,
    )
    .map(|result| result.type_.get());

    // If there was no object.__new__ or it's not a callable, then something has
    // gone terribly wrong in the typeshed stubs. To avoid crashing, simply
    // return the instance.
    let Some(new_method_type) = new_method_type.filter(|&t| is_function_or_overloaded(t)) else {
        return CallResult {
            return_type: Some(convert_to_instance(type_.0, true)),
            ..Default::default()
        };
    };

    validate_new_method(
        evaluator,
        error_node,
        arg_list,
        type_,
        /* skipUnknownArgCheck */ Some(false),
        inference_context,
        P::new_eval(TypeResult::new(new_method_type)),
        /* useSpeculativeModeForArgs */ false,
    )
}

// analyzer/constructors.ts:590
pub(crate) fn validate_metaclass_call(
    evaluator: &TypeEvaluator,
    error_node: ExpressionNode,
    arg_list: &[Arg],
    type_: ClassType,
    skip_unknown_arg_check: Option<bool>,
    inference_context: Option<P<InferenceContext>>,
    use_speculative_mode_for_args: bool,
) -> Option<CallResult> {
    let metaclass_call_method_info = get_bound_call_method(evaluator, error_node, type_)?;

    let call_result = evaluator.use_speculative_mode(
        if use_speculative_mode_for_args {
            Some(error_node)
        } else {
            None
        },
        &mut || {
            evaluator.validate_call_args(
                error_node,
                arg_list,
                metaclass_call_method_info,
                /* constraints */ None,
                skip_unknown_arg_check,
                inference_context,
                0,
            )
        },
        None,
    );

    if !call_result.argument_errors.unwrap_or(false) {
        // If the return type is unannotated, don't use the inferred return type.
        let call_type = metaclass_call_method_info.type_.get();
        if is_function(call_type)
            && FunctionType(call_type)
                .d()
                .shared
                .get()
                .declared_return_type
                .get()
                .is_none()
        {
            return None;
        }

        // If the return type is unknown, ignore it.
        if call_result.return_type.is_some_and(is_unknown) {
            return None;
        }
    }

    Some(call_result)
}

// analyzer/constructors.ts:632
pub(crate) fn apply_expected_subtype_for_constructor(
    evaluator: &TypeEvaluator,
    type_: ClassType,
    expected_subtype: P<Type>,
    constraints: P<ConstraintTracker>,
) -> Option<P<Type>> {
    let specialized_type = evaluator.solve_and_apply_constraints(
        ClassType::clone_as_instance(type_, true).0,
        constraints,
        Some(&ApplyTypeVarOptions {
            type_class_type: None,
            replace_unsolved: Some(ApplyTypeVarOptionsReplaceUnsolved {
                scope_ids: vec![],
                tuple_class_type: evaluator.get_tuple_class_type(),
                unsolved_exempt_type_vars: None,
                use_unknown: None,
                eliminate_unsolved_in_unions: None,
            }),
        }),
        None,
    );

    if !evaluator.assign_type(
        expected_subtype,
        specialized_type,
        None,
        None,
        AssignTypeFlags::Default,
        0,
    ) {
        return None;
    }

    // If the expected type is "Any", transform it to an Any.
    if is_any(expected_subtype) {
        return Some(expected_subtype);
    }

    Some(specialized_type)
}

// analyzer/constructors.ts:659
// Handles the case where a constructor is a generic type and the type
// arguments are not specified but can be provided by the expected type.
pub(crate) fn apply_expected_type_for_constructor(
    evaluator: &TypeEvaluator,
    type_: ClassType,
    inference_context: Option<P<InferenceContext>>,
    constraints: P<ConstraintTracker>,
) -> P<Type> {
    let mut default_if_not_found = true;

    // If this isn't a generic type or it's a type that has already been
    // explicitly specialized, the expected type isn't applicable.
    if type_.d().shared.get().type_params.borrow().is_empty()
        || type_.d().priv_.borrow().type_args.is_some()
    {
        return evaluator.solve_and_apply_constraints(
            ClassType::clone_as_instance(type_, true).0,
            constraints,
            Some(&ApplyTypeVarOptions {
                type_class_type: None,
                replace_unsolved: Some(ApplyTypeVarOptionsReplaceUnsolved {
                    scope_ids: vec![],
                    tuple_class_type: evaluator.get_tuple_class_type(),
                    unsolved_exempt_type_vars: None,
                    use_unknown: None,
                    eliminate_unsolved_in_unions: None,
                }),
            }),
            None,
        );
    }

    if let Some(inference_context) = inference_context {
        let specialized_expected_type = map_subtypes(
            inference_context.expected_type.get(),
            &mut |expected_subtype| {
                apply_expected_subtype_for_constructor(
                    evaluator,
                    type_,
                    expected_subtype,
                    constraints,
                )
            },
            None,
        );

        if !is_never(specialized_expected_type) {
            return specialized_expected_type;
        }

        // If the expected type didn't provide TypeVar values, remaining
        // unsolved TypeVars should be considered Unknown unless they were
        // provided explicitly in the constructor call.
        if type_.d().priv_.borrow().type_args.is_some() {
            default_if_not_found = false;
        }
    }

    let specialized_type = ClassType(evaluator.solve_and_apply_constraints(
        type_.0,
        constraints,
        Some(&ApplyTypeVarOptions {
            type_class_type: None,
            replace_unsolved: if default_if_not_found {
                Some(ApplyTypeVarOptionsReplaceUnsolved {
                    scope_ids: get_type_var_scope_ids(type_.0),
                    tuple_class_type: evaluator.get_tuple_class_type(),
                    unsolved_exempt_type_vars: None,
                    use_unknown: None,
                    eliminate_unsolved_in_unions: None,
                })
            } else {
                None
            },
        }),
        None,
    ));
    ClassType::clone_as_instance(specialized_type, true).0
}

// analyzer/constructors.ts:708
// Similar to applyExpectedTypeForConstructor, this function handles the
// special case of the tuple class.
pub(crate) fn apply_expected_type_for_tuple_constructor(
    type_: ClassType,
    inference_context: Option<P<InferenceContext>>,
) -> ClassType {
    let mut specialized_type = type_;

    if let Some(inference_context) = inference_context
        && is_class_instance(inference_context.expected_type.get())
        && is_tuple_class(ClassType(inference_context.expected_type.get()))
    {
        let expected_tuple_type_args = ClassType(inference_context.expected_type.get())
            .d()
            .priv_
            .borrow()
            .tuple_type_args
            .clone();
        if let Some(expected_tuple_type_args) = expected_tuple_type_args {
            specialized_type =
                specialize_tuple_class(type_, &expected_tuple_type_args, true, false);
        }
    }

    specialized_type
}

// analyzer/constructors.ts:725
// Synthesize a function that represents the constructor for this class
// taking into consideration the __init__ and __new__ methods.
/// TS defaults: selfType = undefined, recursionCount = 0.
pub fn create_function_from_constructor(
    evaluator: &TypeEvaluator,
    class_type: ClassType,
    self_type: Option<P<Type>>,
    recursion_count: u32,
) -> Option<P<Type>> {
    let from_metaclass_call =
        create_function_from_metaclass_call(evaluator, class_type, recursion_count);
    if from_metaclass_call.is_some() {
        return from_metaclass_call;
    }

    let mut from_new =
        create_function_from_new_method(evaluator, class_type, self_type, recursion_count);

    if let Some(from_new) = from_new {
        let mut skip_init_method = false;

        do_for_each_signature(from_new, &mut |signature, _| {
            let new_method_return_type = FunctionType::get_effective_return_type(signature, true);
            if let Some(new_method_return_type) = new_method_return_type
                && should_skip_init_evaluation(evaluator, class_type, new_method_return_type)
            {
                skip_init_method = true;
            }
        });

        if skip_init_method {
            return Some(from_new);
        }
    }

    let from_init =
        create_function_from_init_method(evaluator, class_type, self_type, recursion_count);

    // If there is a valid __init__ method and the __new__ method
    // is the default __new__ method provided by the object class,
    // discard the __new__ method.
    if from_init.is_some() && from_new.is_some() && is_default_new_method(from_new) {
        from_new = None;
    }

    // If there is both a __new__ and __init__ method, return a union
    // comprised of both resulting function types.
    if let (Some(from_new), Some(from_init)) = (from_new, from_init) {
        return Some(combine_types(&[from_init, from_new], None));
    }

    if from_new.is_some() || from_init.is_some() {
        return from_new.or(from_init);
    }

    Some(from_new.unwrap_or_else(|| create_function_from_object_new_method(class_type).0))
}

// analyzer/constructors.ts:775
pub(crate) fn create_function_from_metaclass_call(
    evaluator: &TypeEvaluator,
    class_type: ClassType,
    recursion_count: u32,
) -> Option<P<Type>> {
    let metaclass = class_type.d().shared.get().effective_metaclass.get()?;
    if !is_class(metaclass) {
        return None;
    }

    let call_info = look_up_class_member(
        ClassType(metaclass),
        "__call__",
        MemberAccessFlags::SkipInstanceMembers
            | MemberAccessFlags::SkipTypeBaseClass
            | MemberAccessFlags::SkipAttributeAccessOverride,
        None,
    )?;

    let call_type = evaluator.get_type_of_member(&call_info);
    if !is_function_or_overloaded(call_type) {
        return None;
    }

    let bound_call_type = evaluator.bind_function_to_class_or_object(
        Some(class_type),
        call_type,
        if is_instantiable_class(call_info.class_type) {
            Some(ClassType(call_info.class_type))
        } else {
            None
        },
        /* treatConstructorAsClassMethod */ false,
        Some(class_type.0),
        /* diag */ None,
        recursion_count,
    )?;

    let mut use_metaclass_call = false;

    // Look at the signatures of all the __call__ methods to determine whether
    // any of them returns something other than the instance of the class being
    // constructed.
    do_for_each_signature(bound_call_type, &mut |signature, _| {
        if signature
            .d()
            .shared
            .get()
            .declared_return_type
            .get()
            .is_some()
        {
            let return_type = FunctionType::get_effective_return_type(signature, true);
            if let Some(return_type) = return_type
                && should_skip_new_and_init_evaluation(evaluator, class_type, return_type)
            {
                use_metaclass_call = true;
            }
        }
    });

    if use_metaclass_call {
        Some(bound_call_type)
    } else {
        None
    }
}

// analyzer/constructors.ts:833
pub(crate) fn create_function_from_new_method(
    evaluator: &TypeEvaluator,
    class_type: ClassType,
    self_type: Option<P<Type>>,
    recursion_count: u32,
) -> Option<P<Type>> {
    let new_info = look_up_class_member(
        class_type,
        "__new__",
        MemberAccessFlags::SkipInstanceMembers
            | MemberAccessFlags::SkipAttributeAccessOverride
            | MemberAccessFlags::SkipObjectBaseClass,
        None,
    )?;

    let new_type = evaluator.get_type_of_member(&new_info);

    let convert_new_to_constructor = |new_subtype: FunctionType| -> Option<FunctionType> {
        // If there are no parameters that include class-scoped type parameters,
        // self-specialize the class because the type arguments for the class
        // can't be solved if there are no parameters to supply them.
        let param_count = new_subtype.d().shared.get().parameters.get().borrow().len();
        let has_params_with_type_vars = (0..param_count).any(|index| {
            let has_name = new_subtype.d().shared.get().parameters.get().borrow()[index]
                .name
                .as_deref()
                .is_some_and(|name| !name.is_empty());
            if index == 0 || !has_name {
                return false;
            }

            let param_type = FunctionType::get_param_type(new_subtype, index as i32);
            let type_vars = get_type_var_args_recursive(param_type, 0);
            type_vars.iter().any(|type_var| {
                type_var.d().priv_.borrow().scope_id == get_type_var_scope_id(class_type.0)
            })
        });

        let bound_new = evaluator.bind_function_to_class_or_object(
            Some(if has_params_with_type_vars {
                self_specialize_class(class_type, None)
            } else {
                class_type
            }),
            new_subtype.0,
            if is_instantiable_class(new_info.class_type) {
                Some(ClassType(new_info.class_type))
            } else {
                None
            },
            /* treatConstructorAsClassMethod */ true,
            self_type,
            /* diag */ None,
            recursion_count,
        )?;
        let bound_new = FunctionType(bound_new);

        let converted_new = FunctionType::clone(bound_new, false, None);
        let converted_new_shared = converted_new.d().shared.get();
        let type_var_scope_id = new_subtype
            .d()
            .shared
            .get()
            .type_var_scope_id
            .borrow()
            .clone();
        *converted_new_shared.type_var_scope_id.borrow_mut() = type_var_scope_id;

        if converted_new_shared.doc_string.borrow().is_none()
            && let Some(doc_string) = &class_type.d().shared.get().doc_string
        {
            *converted_new_shared.doc_string.borrow_mut() = Some(doc_string.clone());
        }

        converted_new_shared.flags.set(
            converted_new_shared.flags.get()
                & !(FunctionTypeFlags::StaticMethod | FunctionTypeFlags::ConstructorMethod),
        );
        let constructor_type_var_scope_id = get_type_var_scope_id(class_type.0);
        converted_new
            .d()
            .priv_
            .borrow_mut()
            .constructor_type_var_scope_id = constructor_type_var_scope_id;

        Some(converted_new)
    };

    if is_function(new_type) {
        return convert_new_to_constructor(FunctionType(new_type)).map(|converted| converted.0);
    }

    if !is_overloaded(new_type) {
        return None;
    }

    let mut new_overloads: Vec<FunctionType> = Vec::new();
    for overload in OverloadedType::get_overloads(OverloadedType(new_type)) {
        let converted = convert_new_to_constructor(overload);
        if let Some(converted) = converted {
            new_overloads.push(converted);
        }
    }

    if new_overloads.is_empty() {
        return None;
    }

    if new_overloads.len() == 1 {
        return Some(new_overloads[0].0);
    }

    Some(OverloadedType::create(&new_overloads, None).0)
}

// analyzer/constructors.ts:921
pub(crate) fn create_function_from_object_new_method(class_type: ClassType) -> FunctionType {
    // Return a fallback constructor based on the object.__new__ method.
    let constructor_function =
        FunctionType::create_synthesized_instance("__new__", FunctionTypeFlags::None);
    constructor_function
        .d()
        .shared
        .get()
        .declared_return_type
        .set(Some(ClassType::clone_as_instance(class_type, true).0));

    // If this is type[T] or a protocol, we don't know what parameters are accepted
    // by the constructor, so add the default parameters.
    if class_type
        .d()
        .priv_
        .borrow()
        .include_subclasses
        .unwrap_or(false)
        || ClassType::is_protocol_class(class_type)
    {
        FunctionType::add_default_params(constructor_function, false);
    }

    let constructor_shared = constructor_function.d().shared.get();
    if constructor_shared.doc_string.borrow().is_none()
        && let Some(doc_string) = &class_type.d().shared.get().doc_string
    {
        *constructor_shared.doc_string.borrow_mut() = Some(doc_string.clone());
    }

    constructor_function
}

// analyzer/constructors.ts:939
/// Nested in the TS body: convertInitToConstructor (:961).
pub(crate) fn create_function_from_init_method(
    evaluator: &TypeEvaluator,
    class_type: ClassType,
    self_type: Option<P<Type>>,
    recursion_count: u32,
) -> Option<P<Type>> {
    // Use the __init__ method if available. It's usually more detailed.
    let init_info = look_up_class_member(
        class_type,
        "__init__",
        MemberAccessFlags::SkipInstanceMembers
            | MemberAccessFlags::SkipAttributeAccessOverride
            | MemberAccessFlags::SkipObjectBaseClass,
        None,
    )?;

    let init_type = evaluator.get_type_of_member(&init_info);
    let object_type = ClassType::clone_as_instance(class_type, true);

    // convertInitToConstructor, nested in the TS body at constructors.ts:961.
    let convert_init_to_constructor = |init_subtype: FunctionType| -> Option<FunctionType> {
        let bound_init = evaluator.bind_function_to_class_or_object(
            Some(object_type),
            init_subtype.0,
            if is_instantiable_class(init_info.class_type) {
                Some(ClassType(init_info.class_type))
            } else {
                None
            },
            /* treatConstructorAsClassMethod */ false,
            self_type,
            /* diag */ None,
            recursion_count,
        )?;
        let bound_init = FunctionType(bound_init);

        let converted_init = FunctionType::clone(bound_init, false, None);
        let mut return_type = self_type;
        if return_type.is_none() {
            return_type = Some(object_type.0);

            // If this is a generic type, self-specialize the class (i.e. fill in
            // its own type parameters as type arguments).
            if !object_type.d().shared.get().type_params.borrow().is_empty()
                && object_type.d().priv_.borrow().type_args.is_none()
            {
                let constraints = ConstraintTracker::new();

                // If a TypeVar is not used in any of the parameter types, it should take
                // on its default value (typically Unknown) in the resulting specialized type.
                let mut type_vars_in_params: Vec<TypeVarType> = Vec::new();

                let param_count = converted_init
                    .d()
                    .shared
                    .get()
                    .parameters
                    .get()
                    .borrow()
                    .len();
                for index in 0..param_count {
                    let param_type = FunctionType::get_param_type(converted_init, index as i32);
                    add_type_vars_to_list_if_unique(
                        &mut type_vars_in_params,
                        &get_type_var_args_recursive(param_type, 0),
                        None,
                    );
                }

                for &type_var in &type_vars_in_params {
                    constraints.set_bounds(type_var, Some(type_var.0), None, None);
                }

                return_type = Some(evaluator.solve_and_apply_constraints(
                    object_type.0,
                    constraints,
                    Some(&ApplyTypeVarOptions {
                        type_class_type: None,
                        replace_unsolved: Some(ApplyTypeVarOptionsReplaceUnsolved {
                            scope_ids: get_type_var_scope_ids(object_type.0),
                            tuple_class_type: evaluator.get_tuple_class_type(),
                            unsolved_exempt_type_vars: None,
                            use_unknown: None,
                            eliminate_unsolved_in_unions: None,
                        }),
                    }),
                    None,
                ));
            }
        }

        let converted_init_shared = converted_init.d().shared.get();
        let stripped_first_param_type = bound_init.d().priv_.borrow().stripped_first_param_type;
        converted_init_shared
            .declared_return_type
            .set(stripped_first_param_type.or(return_type));

        let specialized_types = converted_init.d().priv_.borrow().specialized_types;
        if let Some(specialized_types) = specialized_types {
            specialized_types.return_type.set(return_type);
        }

        if converted_init_shared.doc_string.borrow().is_none()
            && let Some(doc_string) = &class_type.d().shared.get().doc_string
        {
            *converted_init_shared.doc_string.borrow_mut() = Some(doc_string.clone());
        }

        converted_init_shared
            .flags
            .set(converted_init_shared.flags.get() & !FunctionTypeFlags::StaticMethod);
        let constructor_type_var_scope_id = get_type_var_scope_id(class_type.0);
        converted_init
            .d()
            .priv_
            .borrow_mut()
            .constructor_type_var_scope_id = constructor_type_var_scope_id;

        Some(converted_init)
    };

    if is_function(init_type) {
        return convert_init_to_constructor(FunctionType(init_type)).map(|converted| converted.0);
    }

    if !is_overloaded(init_type) {
        return None;
    }

    let mut init_overloads: Vec<FunctionType> = Vec::new();
    for overload in OverloadedType::get_overloads(OverloadedType(init_type)) {
        let converted = convert_init_to_constructor(overload);
        if let Some(converted) = converted {
            init_overloads.push(converted);
        }
    }

    if init_overloads.is_empty() {
        return None;
    }

    if init_overloads.len() == 1 {
        return Some(init_overloads[0].0);
    }

    Some(OverloadedType::create(&init_overloads, None).0)
}

// analyzer/constructors.ts:1053
// If the __call__ method returns a type that is not an instance of the class,
// skip the __new__ and __init__ method evaluation.
pub(crate) fn should_skip_new_and_init_evaluation(
    evaluator: &TypeEvaluator,
    class_type: ClassType,
    call_method_return_type: P<Type>,
) -> bool {
    if !evaluator.assign_type(
        convert_to_instance(class_type.0, true),
        call_method_return_type,
        None,
        None,
        AssignTypeFlags::Default,
        0,
    ) || is_never(call_method_return_type)
        || find_subtype(call_method_return_type, &mut |subtype| is_any(subtype)).is_some()
    {
        return true;
    }

    // Handle the special case of an enum class, where the __new__ and __init__
    // methods are replaced at runtime by the metaclass.
    if ClassType::is_enum_class(class_type) {
        return true;
    }

    false
}

// analyzer/constructors.ts:1078
// If __new__ returns a type that is not an instance of the class, skip the
// __init__ method evaluation. This is consistent with the behavior of the
// type.__call__ runtime behavior.
pub(crate) fn should_skip_init_evaluation(
    evaluator: &TypeEvaluator,
    class_type: ClassType,
    new_method_return_type: P<Type>,
) -> bool {
    let return_type =
        evaluator.make_top_level_type_vars_concrete(new_method_return_type, false, None);

    let mut skip_init_check = false;
    do_for_each_subtype(
        return_type,
        &mut |subtype, _, _| {
            if is_unknown(subtype) {
                return;
            }

            if is_class_instance(subtype) {
                let mut inheritance_chain: InheritanceChain = Vec::new();
                let is_derived_from = ClassType::is_derived_from(
                    ClassType::clone_as_instantiable(ClassType(subtype), true),
                    class_type,
                    Some(&mut inheritance_chain),
                );

                if !is_derived_from {
                    skip_init_check = true;
                }

                return;
            }

            skip_init_check = true;
        },
        false,
    );

    skip_init_check
}

// analyzer/constructors.ts:1111
// Determine whether the __new__ method is the placeholder signature
// of "def __new__(cls, *args, **kwargs) -> Self" or
// "def __new__(cls, /, *args, **kwargs) -> Self".
pub(crate) fn is_default_new_method(new_method: Option<P<Type>>) -> bool {
    let Some(new_method) = new_method.filter(|&t| is_function(t)) else {
        return false;
    };
    let new_method = FunctionType(new_method);

    let shared = new_method.d().shared.get();
    let parameters = shared.parameters.get();
    let parameters = parameters.borrow();
    let mut params: &[_] = &parameters;

    // After binding, cls is stripped. A positional-only separator may remain
    // if the original signature was "def __new__(cls, /, *args, **kwargs)".
    // Skip the separator when checking for the default pattern.
    if !params.is_empty() && is_position_only_separator(&params[0]) {
        params = &params[1..];
    }

    if params.len() != 2 {
        return false;
    }

    if params[0].category != ParamCategory::ArgsList
        || params[1].category != ParamCategory::KwargsDict
    {
        return false;
    }

    let return_type: Option<P<Type>> =
        if let Some(declared_return_type) = shared.declared_return_type.get() {
            Some(declared_return_type)
        } else {
            new_method
                .d()
                .priv_
                .borrow()
                .specialized_types
                .and_then(|specialized_types| specialized_types.return_type.get())
                .or_else(|| {
                    shared
                        .inferred_return_type
                        .borrow()
                        .as_ref()
                        .map(|inferred| inferred.type_)
                })
        };

    let Some(return_type) = return_type.filter(|&t| is_type_var(t)) else {
        return false;
    };
    if !TypeVarType::is_self(TypeVarType(return_type)) {
        return false;
    }

    true
}
